def make_education_words():
    words = []
    subs = ["education_school", "education_university", "education_supplies", "education_languages", "education_exams"]
    for i, w in enumerate(education_data):
        sub = subs[i // 50]
        words.append((w[0], w[1], w[2], f"[{w[0].lower()}]", w[3], w[4], w[5], w[6], "education", sub, w[7]))
    return words

EDUCATION_WORDS = make_education_words()
print("Education words generated:", len(EDUCATION_WORDS))
